package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.function.Supplier;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.Dues;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;

/**
 * The figures a sheet rolls up to: what each person has claimed, their due-total and their
 * overdue-total, and the sheet's totals of all three. The sheet's due-total and overdue-total leave
 * out the single highest and the single lowest person's figure when three or more people have one
 * (a due-total of n/a is no figure). A change made through {@link #tracking} is followed in the audit by one
 * ROLLUP line per person whose figures it moved (in the order they were added), then a TOTALS line
 * when the sheet's totals moved.
 */
@Service
public class Rollup {

    /** A person's figures as two-decimal text; a due-total of n/a is "n/a". */
    private record Figures(String name, String claimed, String dueTotal, String overdueTotal) {
        boolean sameAs(Figures other) {
            return other != null && claimed.equals(other.claimed) && dueTotal.equals(other.dueTotal)
                    && overdueTotal.equals(other.overdueTotal);
        }
    }

    /** The figures of a sheet: each person's by id in the order they were added, and the totals. */
    private record Snapshot(Map<Long, Figures> people, String claimedTotal, String dueTotal,
            String overdueTotal) {
    }

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final Dues dues;
    private final SheetService sheets;
    private final Audit audit;

    public Rollup(PersonRepository people, ClaimRepository claims, Dues dues, SheetService sheets, Audit audit) {
        this.people = people;
        this.claims = claims;
        this.dues = dues;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** Make a change on the sheet, then record in the audit, after the change's own records, the
     *  figures it moved. A change that is refused records nothing. */
    @Transactional(propagation = Propagation.MANDATORY)
    public <T> T tracking(String sheetId, String user, Supplier<T> change) {
        Snapshot before = snapshot(sheetId);
        T result = change.get();
        Snapshot after = snapshot(sheetId);
        String prefix = " sheet=" + sheetId + " by=" + user;
        after.people().forEach((id, figures) -> {
            if (!figures.sameAs(before.people().get(id))) {
                audit.recordOnCommit("ROLLUP" + prefix + " person=" + figures.name()
                        + " claimed=" + figures.claimed() + " due-total=" + figures.dueTotal()
                        + " overdue-total=" + figures.overdueTotal());
            }
        });
        if (!Objects.equals(before.claimedTotal(), after.claimedTotal())
                || !Objects.equals(before.dueTotal(), after.dueTotal())
                || !Objects.equals(before.overdueTotal(), after.overdueTotal())) {
            audit.recordOnCommit("TOTALS" + prefix + " claimed-total=" + after.claimedTotal()
                    + " due-total=" + after.dueTotal() + " overdue-total=" + after.overdueTotal());
        }
        return result;
    }

    private Snapshot snapshot(String sheetId) {
        Map<Long, List<Claim>> byPerson = claims.findBySheetIdOrderByListedDesc(sheetId).stream()
                .collect(Collectors.groupingBy(Claim::getPersonId));
        Map<Long, Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
        List<BigDecimal> dueFigures = new ArrayList<>();
        List<BigDecimal> overdueFigures = new ArrayList<>();
        LocalDate today = sheets.today(sheetId);
        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
            List<Claim> theirs = Dues.live(person, byPerson.getOrDefault(person.getId(), List.of()), today);
            BigDecimal claimed = theirs.stream().map(Claim::getAmount)
                    .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
            BigDecimal due = dues.dueTotal(sheetId, person, theirs);
            BigDecimal overdue = theirs.stream().filter(c -> c.getStatus().isOpen() && c.getDueBy().isBefore(today))
                    .map(c -> dues.figure(sheetId, person, c)).filter(Objects::nonNull)
                    .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
            claimedTotal = claimedTotal.add(claimed);
            overdueFigures.add(overdue);
            if (due != null) {
                dueFigures.add(due);
            }
            figures.put(person.getId(), new Figures(person.getName(), text(claimed),
                    due == null ? "n/a" : text(due), text(overdue)));
        }
        return new Snapshot(figures, text(claimedTotal), text(trimmedSum(dueFigures)), text(trimmedSum(overdueFigures)));
    }

    /** The figures added up, leaving out the single highest and the single lowest when there are
     *  three or more. */
    private static BigDecimal trimmedSum(List<BigDecimal> figures) {
        List<BigDecimal> kept = new ArrayList<>(figures);
        if (kept.size() >= 3) {
            kept.sort(Comparator.naturalOrder());
            kept = kept.subList(1, kept.size() - 1);
        }
        return kept.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
    }

    private static String text(BigDecimal value) {
        return value.setScale(2).toPlainString();
    }
}
package net.officefloor.hq.app.person;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.sheet.SheetService;
import net.officefloor.hq.app.statement.StatementService;
import net.officefloor.hq.app.statement.StatementSummary;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.server.ResponseStatusException;

@RestController
@RequestMapping("/api/sheets/{sheetId}/people")
@Validated
public class PersonController {

    /** What the screen shows of a person; with how many statements were taken of them, and the
     *  last one's due-total (text with two decimals, null when n/a or none) and day (null when none);
     *  whether they are retired, and from which day (null when not); and whether they have any hold, and their holds, earliest first; and their own terms in days (null: none).
     *  The grade is the one in force on the sheet's today; grades are all those recorded, each from
     *  its from-date (null: the beginning of time), earliest first. */
    public record PersonView(long id, String name, String grade, List<GradeView> grades, long version,
            int statementCount, String statedTotal, LocalDate statementDate, boolean retired, LocalDate retiredFrom,
            boolean held, List<HoldView> holds, Integer terms) {
        public static PersonView of(Person person, StatementSummary statements, LocalDate today) {
            return new PersonView(person.getId(), person.getName(), person.gradeOn(today),
                    person.getGrades().stream().map(g -> new GradeView(g.getGrade(), g.getFromDate())).toList(),
                    person.getVersion(), statements.count(),
                    statements.lastDueTotal() == null ? null : statements.lastDueTotal().setScale(2).toPlainString(),
                    statements.lastTakenOn(), person.isRetired(), person.getRetiredFrom(), person.isHeld(),
                    person.getHolds().stream().map(h -> new HoldView(h.getFromDate(), h.getToDate())).toList(),
                    person.getTerms());
        }
    }

    /** A grade recorded for a person, from a day (null: from the beginning of time). */
    public record GradeView(String grade, LocalDate from) {
    }

    /** A hold on a person, from a day (null: from the beginning of time) to a day (null: open-ended). */
    public record HoldView(LocalDate from, LocalDate to) {
    }

    /** The person form: a required name and a grade of A, B or C. An edit also gives the version
     *  of the person its editor loaded, and the day the grade applies from (left out, the sheet's
     *  today). Terms are the person's own, a whole number of days, 0 or more; blank for none. */
    public record PersonForm(@NotBlank @Size(max = 200) String name,
            @NotNull @Pattern(regexp = "[ABC]") String grade, Long version, LocalDate gradeFrom,
            @Pattern(regexp = "\\s*\\d{0,4}\\s*") String terms) {
        Integer termsValue() {
            return terms == null || terms.isBlank() ? null : Integer.valueOf(terms.trim());
        }
    }

    /** The retire form: the day the person is retired from; left out, the sheet's today. */
    public record RetireForm(LocalDate from) {
    }

    /** The hold form: the day the hold starts (left out, the sheet's today) and the day it ends
     *  (left out, it is open-ended). */
    public record HoldForm(LocalDate from, LocalDate to) {
    }

    private final PersonService service;
    private final StatementService statements;
    private final SheetService sheets;

    public PersonController(PersonService service, StatementService statements, SheetService sheets) {
        this.service = service;
        this.statements = statements;
        this.sheets = sheets;
    }

    @GetMapping
    public List<PersonView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId) {
        String sheet = sheetId.trim();
        Map<Long, StatementSummary> summaries = statements.summaries(sheet);
        LocalDate today = sheets.today(sheet);
        return service.list(sheet).stream()
                .map(p -> PersonView.of(p, summaries.getOrDefault(p.getId(), StatementSummary.NONE), today))
                .toList();
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public PersonView add(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody PersonForm form) {
        return PersonView.of(service.add(sheetId.trim(), user.trim(), form.name().trim(), form.grade(),
                form.termsValue()),
                StatementSummary.NONE, sheets.today(sheetId.trim()));
    }

    @PutMapping("/{personId}")
    public PersonView edit(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody PersonForm form) {
        if (form.version() == null) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The version of the person edited is required");
        }
        Person saved = service.edit(sheetId.trim(), user.trim(), personId, form.version(), form.name().trim(),
                form.grade(), form.gradeFrom(), form.termsValue());
        return PersonView.of(saved, statements.summary(sheetId.trim(), personId), sheets.today(sheetId.trim()));
    }

    @PostMapping("/{personId}/retire")
    public PersonView retire(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody RetireForm form) {
        Person saved = service.retire(sheetId.trim(), user.trim(), personId, form.from());
        return PersonView.of(saved, statements.summary(sheetId.trim(), personId), sheets.today(sheetId.trim()));
    }

    @PostMapping("/{personId}/hold")
    public PersonView hold(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody HoldForm form) {
        Person saved = service.hold(sheetId.trim(), user.trim(), personId, form.from(), form.to());
        return PersonView.of(saved, statements.summary(sheetId.trim(), personId), sheets.today(sheetId.trim()));
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.List;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;

/** The due figures of claims, and the due-totals of people, at the rates on a sheet. */
@Service
public class Dues {

    private final RateRepository rates;
    private final SheetService sheets;

    public Dues(RateRepository rates, SheetService sheets) {
        this.rates = rates;
        this.sheets = sheets;
    }

    /** The due figure a claim shows and totals: the one fixed when it was settled, or else its
     *  {@link #bindable} rate figure with the late charge on that figure on top while it is overdue,
     *  at least the sheet's floor in force on the claim's date (a correction has neither); null when
     *  there is none. */
    public BigDecimal figure(String sheetId, Person person, Claim claim) {
        if (claim.getSettledDue() != null) {
            return claim.getSettledDue();
        }
        return floored(sheetId, claim, bindable(sheetId, person, claim), claim.getStatus().isOpen());
    }

    /** The figure a claim would have today as an open claim bound by no statement: its rate figure
     *  with the late charge on top while it is overdue, at least the floor in force on its date; null
     *  when there is none. */
    public BigDecimal openFigure(String sheetId, Person person, Claim claim) {
        return floored(sheetId, claim, due(sheetId, person, claim), true);
    }

    /** A rate figure with its late charge (taken as open or not) on top, then at least the sheet's
     *  floor in force on the claim's date (a correction has no floor); null when the figure is. */
    private BigDecimal floored(String sheetId, Claim claim, BigDecimal figure, boolean open) {
        if (figure == null) {
            return null;
        }
        BigDecimal charged = figure.add(lateCharge(sheetId, claim, figure, open));
        return claim.isCorrection() ? charged : charged.max(sheets.floor(sheetId, claim.getDate()));
    }

    /** The rate figure a statement binds a claim to: the one its person's last statement bound it to,
     *  or else its live rate figure (a pending claim is not bound by a statement while it is pending);
     *  never the late charge, which keeps following the sheet's today, nor the floor, which is applied
     *  last. Null when there is none, or when the statement bound it to n/a. */
    public BigDecimal bindable(String sheetId, Person person, Claim claim) {
        if (bound(claim) && (claim.getStatedDue() != null || claim.isStatedNa())) {
            return claim.getStatedDue();
        }
        return due(sheetId, person, claim);
    }

    /** Whether a statement binds a claim to n/a: its person's last statement bound it to n/a, or
     *  else it has no bound figure and no live due because the rate that would apply to it on its
     *  date (for the person's grade on that date) has ended. */
    public boolean bindsNa(String sheetId, Person person, Claim claim) {
        if (bound(claim) && (claim.getStatedDue() != null || claim.isStatedNa())) {
            return claim.isStatedNa();
        }
        return due(sheetId, person, claim) == null
                && rates.endedBefore(sheetId, person.gradeOn(claim.getDate()), claim.getDate());
    }

    /** Whether a claim is bound by its person's last statement now (a pending claim is not). */
    private static boolean bound(Claim claim) {
        return claim.isStated() && claim.getStatus() != ClaimStatus.PENDING;
    }

    /** The late charge on a claim taken as open (or pending) or not, overdue on the sheet's today (its due-by, fixed when it was
     *  made, before today; a correction has none): for each full 30 days it is overdue, the late percent in force on
     *  that boundary (its due-by plus 30, 60, 90 ... days) of its figure, rounded to two decimals by the claim's
     *  {@link #rounding}, the charges added up (a boundary whose percent is 0.00 adds nothing); 0.00 when it is not overdue. */
    private BigDecimal lateCharge(String sheetId, Claim claim, BigDecimal figure, boolean open) {
        BigDecimal none = BigDecimal.ZERO.setScale(2);
        if (!open || claim.isCorrection() || claim.isDeferredOn(sheets.today(sheetId))) {
            return none;
        }
        long periods = ChronoUnit.DAYS.between(claim.getDueBy(), sheets.today(sheetId)) / 30;
        if (periods <= 0) {
            return none;
        }
        RoundingMode rounding = rounding(sheetId, claim);
        BigDecimal charge = none;
        for (long n = 1; n <= periods; n++) {
            BigDecimal pct = sheets.latePct(sheetId, claim.getDueBy().plusDays(30 * n));
            if (pct.signum() != 0) {
                charge = charge.add(figure.multiply(pct).movePointLeft(2).setScale(2, rounding));
            }
        }
        return charge;
    }

    /** Whether a claim of the person counts in the live totals on the sheet's today: it counts, it is
     *  not deferred on that day, and it is not an open (or pending) claim, unbound by a statement,
     *  dated within one of the person's holds. */
    public static boolean countsLive(Person person, Claim claim, LocalDate today) {
        return claim.getStatus().counts() && !claim.isDeferredOn(today)
                && !(claim.getStatus().isOpen() && !claim.isStated() && person.isHeldOn(claim.getDate()));
    }

    /** Whether a claim of the person counts in a period's totals: by the status it had at the end of
     *  the period's last day (see Claim#statusOn) it counts, and the live rules do not leave it out:
     *  it is not deferred on the sheet's today, and it is not a claim open (or pending) now,
     *  unbound by a statement, dated within one of the person's holds. */
    public static boolean countsAsOf(Person person, Claim claim, LocalDate end, LocalDate today) {
        ClaimStatus then = claim.statusOn(end);
        return then != null && then.counts() && !claim.isDeferredOn(today)
                && !(claim.getStatus().isOpen() && !claim.isStated() && person.isHeldOn(claim.getDate()));
    }

    /** The claims of a person that count in the live totals on the sheet's today. */
    public static List<Claim> live(Person person, List<Claim> theirs, LocalDate today) {
        return theirs.stream().filter(c -> countsLive(person, c, today)).toList();
    }

    /** A person's due-total: the sum of the figures of their claims that count, at most the sheet's
     *  cap in force on its today; null (n/a) when their grade on the sheet's today has no rate on it and no counting claim
     *  has a figure (one fixed, or a live due at the grade in force on its date). */
    public BigDecimal dueTotal(String sheetId, Person person, List<Claim> theirs) {
        List<BigDecimal> figures = theirs.stream().filter(c -> c.getStatus().counts())
                .map(c -> figure(sheetId, person, c)).filter(d -> d != null).toList();
        LocalDate today = sheets.today(sheetId);
        boolean rated = rates.findInForce(sheetId, person.gradeOn(today), today).isPresent();
        if (!rated && figures.isEmpty()) {
            return null;
        }
        BigDecimal sum = figures.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
        BigDecimal cap = sheets.cap(sheetId);
        return cap == null ? sum : sum.min(cap);
    }

    /** A claim's live due at the rate, in force on the claim's date, for the person's grade in force
     *  on that date: amount
     *  times pct divided by 100, rounded to two decimals by the claim's {@link #rounding} (the floor is
     *  applied later, see {@link #floored}); null when no rate applies on that date. */
    private BigDecimal due(String sheetId, Person person, Claim claim) {
        RoundingMode rounding = rounding(sheetId, claim);
        return rates.findInForce(sheetId, person.gradeOn(claim.getDate()), claim.getDate())
                .map(Rate::getPct)
                .map(pct -> claim.getAmount().multiply(pct).movePointLeft(2).setScale(2, rounding))
                .orElse(null);
    }

    /** How a claim's live figures round: half up when the date it rounds by (a correction's is that of
     *  the claim it corrects) is before the sheet's policy date, else half to even. */
    private RoundingMode rounding(String sheetId, Claim claim) {
        return claim.roundsBy().isBefore(sheets.policyDateInForce(sheetId)) ? RoundingMode.HALF_UP
                : RoundingMode.HALF_EVEN;
    }
}
